INSERT INTO `proyectos_negocio` VALUES (1,'test-agent-123','2026-01-13 15:04:18','2026-01-13 15:04:18','borrador','v1.0','Test Business','Test User',NULL,NULL,'Description',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,'Manual',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2,'demo-user','2026-01-13 15:17:50','2026-01-14 21:19:15','completo','v1.0','Cositas Technologies','Eduardo Celis Robles',NULL,'Cositas es un ecosistema digital integral enfocado en el comercio hiper-local. Su arquitectura principal es un marketplace de MiPymes optimizado para dispositivos de gama baja en México y zonas de baja conectividad.','Cositas ataca la baja competitividad y el crecimiento limitado del comercio de barrio, un problema que surge de la exclusión digital funcional que afecta a más de 60 millones de mexicanos. El ecosistema está compuesto por tres pilares: 1) Marketplace de Descubrimiento (App Nativa para comprador y PWA para vendedor), 2) Asistente IA de Gestión (herramientas CRM/POS), 3) Pasarela de Pagos Offline basada en blockchain.','La solución se centra en tres desafíos principales: 1) Invisibilidad Digital: Los comercios locales no tienen presencia en el mapa digital ni canales fáciles para anunciar sus ofertas. 2) Gestión Ineficiente: Los micro-negocios operan con métodos manuales (el cuaderno) que impiden tomar decisiones estratégicas. 3) Exclusión Financiera: La alta dependencia del efectivo aísla a los comerciantes de la economía digital.','La integración de Marketplace + IA de Gestión + Pagos Offline en un solo ecosistema optimizado para hardware limitado. Nos centramos en la inmediatez con datos en tiempo real (mapa interactivo que muestra el estado Abierto/Cerrado del negocio). El Asistente IA es el ERP del tianguis.','Micro y pequeños comercios de barrio (MiPymes), incluyendo tiendas de abarrotes, taquerías, fruterías, servicios y vendedores ambulantes. Compradores de 18 a 45 años con smartphones de gama baja.',3283692.00,'El equipo fundador cuenta con experiencia en desarrollo de software, tecnologías blockchain y startups tecnológicas.','Empoderar al comercio de barrio con tecnología simple y poderosa, conectándolos con su comunidad y acelerando su crecimiento en la economía digital.','Tiempo completo del equipo fundador y socios','{\"roles\": [{\"id\": 1768323380600.9895, \"name\": \"CEO\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"-\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380600.939, \"name\": \"COO\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"CEO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380600.4, \"name\": \"CTO\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"CEO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380600.5972, \"name\": \"Administración y Finanzas\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"COO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380601.7363, \"name\": \"Soporte y Embajadores\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"COO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380601.1023, \"name\": \"PWA\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"CTO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768323380601.077, \"name\": \"MOVIL\", \"count\": 1, \"salary\": 22500, \"profile\": \"\", \"reportsTo\": \"CTO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768424085658, \"name\": \"Backenend\", \"count\": 1, \"salary\": 10000, \"profile\": \"\", \"reportsTo\": \"CTO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}, {\"id\": 1768424086158, \"name\": \"Blcokchain\", \"count\": 1, \"salary\": 10000, \"profile\": \"\", \"reportsTo\": \"CTO\", \"riskClass\": \"I\", \"responsibilities\": \"\"}], \"canvas\": {\"costs\": [\"Costo Dominante: Salarios del equipo técnico (83.7% inversión inicial)\", \"Costo Variable: CAC (Costo de Adquisición de Clientes) y Publicidad\", \"Costos Fijos: Renta, servicios, impuestos, mantenimiento Red Blockchain\", \"Inversión Total Requerida (Año 1): $32,726,700 MXN\"], \"value\": [\"Para Vendedores: Gestión Digital con Asistente IA (ERP de bajo costo)\", \"Para Vendedores: Visibilidad hiperlocal en tiempo real (mapa Abierto/Cerrado)\", \"Para Compradores: Descubrimiento de ofertas inmediatas\", \"Para Compradores: Pagos Flexibles y Seguros (incluyendo offline)\", \"App optimizada para smartphones gama baja (<2GB RAM)\"], \"revenue\": [\"Comisiones por Transacción Blockchain: 5% al vendedor al retirar saldo\", \"Publicidad Hiper-Local: Historias (48-72h) y Publicaciones con CPC/CPM\", \"Suscripción SaaS Asistente IA: $299/mes o 1% de ventas\", \"Servicios B2B para Proveedores: 1% del valor del pedido\", \"Venta de Datos Agregados anonimizados\", \"Comisiones Pasarelas Terceros: 5% en tarjeta/PayPal/CoDi\", \"Saldos Inactivos y Redondeo para causas sociales\"], \"channels\": [\"App Nativa (Comprador) optimizada para Android\", \"PWA (Vendedor) de bajo consumo de datos\", \"Marketing de referidos y publicidad digital focalizada\", \"Embajadores Digitales en campo\"], \"partners\": [\"Google Firebase/Cloud Platform (infraestructura serverless)\", \"Pasarelas de Pago: Stripe, PayPal, SPEI, CoDi\", \"Cámaras de Comercio (CANACOPE)\", \"Fabricantes de Equipos Originales (OEMs)\", \"Universidades (UNISON)\"], \"segments\": [\"Vendedores: Microcomercios y MiPymes (abarrotes, fondas, servicios) sector formal e informal\", \"Compradores: Población 18-55 años con smartphones gama baja y conectividad limitada\", \"Desarrolladores: Apps lite locales\", \"Proveedores B2B: Empresas de consumo masivo que quieren optimizar rutas de surtido\"], \"resources\": [\"Plataforma Serverless (Firebase)\", \"Red Blockchain Privada para pagos offline\", \"Algoritmos de IA/ML para Asistente\", \"Equipo de desarrollo especializado (CTO, Devs Blockchain/Android)\", \"Registro de marca Cositas y protocolo offline propietario\"], \"activities\": [\"Desarrollo de Software: App y PWA optimizados para gama baja\", \"Adquisición de Usuarios: Marketing de penetración hiperlocal (CAC)\", \"Cumplimiento y Seguridad: Compliance Ley Fintech y LFPDPPP\", \"Curaduría: Gestión del marketplace y perfiles verificados\"], \"relationships\": [\"Soporte Comunitario: Equipo hiperlocalizado y chat directo\", \"Educación Digital: Tutoriales tipo reels para usar POS/IA\", \"Identidad Única: Registro y seguridad basado en CURP\", \"Embajadores Digitales para onboarding y capacitación\"]}}','Compradores: Residentes de la comunidad de 18 a 45 años, tecnológicamente activos, que valoran la conveniencia y la inmediatez. Poseen smartphones de gama baja-media (&lt;2GB RAM, Android 5+) y tienen planes de datos limitados. Vendedores: Micro y pequeños comercios de barrio (MiPymes), con baja digitalización y alta dependencia del efectivo.','Vendedores: Necesitan herramientas digitales simples, visibilidad local, pagos flexibles. Compradores: Buscan conveniencia, descubrimiento de ofertas locales, pagos seguros.','[{\"id\": 1, \"lat\": 29.072656035654543, \"lng\": -110.9603705223633, \"nombre\": \"La Esquina tacos\", \"colonia\": \"San Benito\", \"actividad\": \"tacos\", \"distancia\": 718, \"empleados\": 18}, {\"id\": 2, \"lat\": 29.065674876254302, \"lng\": -110.94794126490538, \"nombre\": \"El Rincón tacos\", \"colonia\": \"Las Quintas\", \"actividad\": \"tacos\", \"distancia\": 265, \"empleados\": 17}, {\"id\": 3, \"lat\": 29.0755249867423, \"lng\": -110.95228604331884, \"nombre\": \"Los Arcos tacos\", \"colonia\": \"Centro\", \"actividad\": \"tacos\", \"distancia\": 712, \"empleados\": 8}, {\"id\": 4, \"lat\": 29.07629178622721, \"lng\": -110.9592639853263, \"nombre\": \"El Portal tacos\", \"colonia\": \"Centro\", \"actividad\": \"tacos\", \"distancia\": 502, \"empleados\": 4}]',NULL,'1) Marketplace de Descubrimiento Hiper-Local con mapa en tiempo real. 2) Plataforma de Pagos Flexible (online y offline). 3) Asistente IA único como ERP del tianguis. 4) Protocolo de Pagos Offline con blockchain (doble confirmación). 5) Diseño optimizado para hardware limitado.',29.07290000,-110.95590000,'Hermosillo, Sonora, México',NULL,'El proceso de desarrollo y prestación del servicio sigue un modelo de desarrollo ágil en tres fases:\\n\\n1. FASE SEMILLA (Meses 1-6): Desarrollo de MVPs, pruebas internas del Asistente IA, integración con pasarela de pagos, lanzamiento piloto en colonia de Hermosillo.\\n\\n2. FASE CRECIMIENTO (Meses 7-18): Expansión a nivel estatal, lanzamiento de versión premium SaaS, alianzas con cámaras de comercio.\\n\\n3. FASE EXPANSIÓN (Año 2-5): Expansión nacional, 20 millones de usuarios, exploración de mercados LATAM.','Meta Año 1: 1,000,000 compradores y 10,000 vendedores. Infraestructura cloud escalable con Firebase.','[{\"producto\": \"App Nativa Comprador\", \"descripcion\": \"Aplicación móvil gratuita para descubrir comercios locales y realizar pagos\", \"precio_venta\": 0}, {\"producto\": \"PWA Vendedor\", \"descripcion\": \"Web App Progresiva para gestionar el negocio, inventario y ventas\", \"precio_venta\": 0}, {\"producto\": \"Asistente IA Premium (SaaS)\", \"descripcion\": \"Versión premium con análisis avanzado, predicciones y automatización\", \"precio_venta\": 299}, {\"producto\": \"Publicidad en Muro\", \"descripcion\": \"Espacios publicitarios en el feed de historias para comercios\", \"precio_venta\": 500}]','[{\"tipo\": \"Tecnología\", \"nombre\": \"Google Firebase/Cloud Platform\", \"producto\": \"Infraestructura serverless\"}, {\"tipo\": \"Fintech\", \"nombre\": \"Stripe\", \"producto\": \"Pasarela de pagos\"}, {\"tipo\": \"Fintech\", \"nombre\": \"PayPal\", \"producto\": \"Pasarela de pagos\"}, {\"tipo\": \"Fintech\", \"nombre\": \"SPEI/CoDi\", \"producto\": \"Transferencias bancarias\"}]','Cositas - Inclusión Digital y Financiera. Colores: Naranja (#F39C12) para energía e identidad local, Azul Profundo (#2C3E50) para confianza y profesionalismo.','Modelo Freemium con múltiples fuentes de ingresos:\\n1. Comisión por retiro de la Billetera Cositas (5%)\\n2. SaaS Asistente IA Premium ($299/mes)\\n3. Publicidad en el Muro ($500/campaña)\\n4. Venta de datos agregados (futuro)\\n5. Comisiones de pasarela de pagos','[\"App Móvil\", \"PWA Web\", \"Redes Sociales\", \"Embajadores Digitales\", \"Alianzas con Cámaras de Comercio\"]','1. Bono de Bienvenida: $100 MXN a los primeros 10,000 usuarios que depositen saldo\\n2. Campaña de Adquisición Digital (CAC promedio $26 MXN)\\n3. Red de Embajadores Digitales para capacitación en campo\\n4. Alianzas con universidades para reclutar embajadores\\n5. Marketing de contenidos sobre inclusión financiera',NULL,NULL,NULL,NULL,50000.00,NULL,NULL,3283692.00,'{\"inversion_total\": 3283692, \"kpis_crecimiento\": {\"cac_usuario\": 26, \"ltv_esperado\": 150, \"usuarios_año1\": 1000000, \"vendedores_año1\": 10000}, \"punto_equilibrio\": {\"volumen_mensual\": 2500000, \"transacciones_mensuales\": 50000}, \"proyeccion_ingresos\": {\"año1\": {\"ingresos\": 1250000, \"transacciones\": 500000, \"comision_promedio\": 2.5}, \"año2\": {\"ingresos\": 5000000, \"transacciones\": 2000000, \"comision_promedio\": 2.5}, \"año3\": {\"ingresos\": 20000000, \"transacciones\": 8000000, \"comision_promedio\": 2.5}}}',NULL,NULL,'Reducción de la brecha digital funcional. Se dirige a la Población Económicamente Activa (PEA) en el sector informal (31.8 millones de personas), dándoles acceso a un ecosistema de pagos que funciona sin internet constante. Promueve la formalización del comercio y la inclusión financiera.','Genera empleos directos (equipo de 7 personas inicial), con proyección de 25 empleos directos a largo plazo. Fortalece la economía local al incentivar el consumo de proximidad. Facilita la facturación (CFDI) actuando como puente para la recaudación fiscal.','{\"foda\": {\"amenazas\": [\"Entrada de grandes competidores al nicho local\", \"Cambios regulatorios en fintech/pagos\", \"Resistencia cultural al cambio digital\", \"Crisis económica que afecte comercio minorista\", \"Ciberseguridad y fraudes\"], \"fortalezas\": [\"Equipo fundador con experiencia en tecnología blockchain y startups\", \"Modelo freemium accesible para comercio informal\", \"Asistente IA personalizado para vendedores\", \"Múltiples fuentes de ingreso (comisiones, SaaS, publicidad)\", \"Infraestructura cloud escalable (Firebase)\"], \"strategies\": {\"da\": \"Diversificar fuentes de ingreso y mantener costos bajos para sobrevivir posibles crisis económicas.\", \"do\": \"Implementar programa de capacitación digital gratuito para superar la curva de aprendizaje de vendedores.\", \"fa\": \"Crear alianzas con cámaras de comercio para ganar credibilidad ante posible entrada de competidores.\", \"fo\": \"Usar el Asistente IA para facilitar la adopción de vendedores sin experiencia digital, aprovechando la necesidad del mercado.\"}, \"debilidades\": [\"Dependencia inicial de adopción de vendedores\", \"Competencia de marketplaces establecidos (Mercado Libre, Facebook)\", \"Necesidad de educación digital para comerciantes tradicionales\", \"Alto costo de adquisición de usuarios (CAC)\", \"Requiere masa crítica para ser rentable\"], \"oportunidades\": [\"Millones de vendedores informales sin presencia digital\", \"Crecimiento del comercio electrónico post-pandemia\", \"Adopción creciente de pagos digitales en México\", \"Alianzas con cámaras de comercio y gobiernos locales\", \"Expansión a LATAM después de consolidar México\"]}}',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,'Manual',NULL,NULL,NULL,'{\"fase_semilla\": \"Meses 1-6: Desarrollo MVPs, pruebas internas Asistente IA, integración pasarela de pagos, lanzamiento piloto en colonia de Hermosillo\", \"fase_expansion\": \"Año 2-5: Expansión nacional, 20 millones de usuarios, exploración mercados LATAM\", \"fase_crecimiento\": \"Meses 7-18: Expansión estatal, lanzamiento SaaS premium, alianzas con cámaras de comercio\"}',NULL,'{\"tasaISR\": 30, \"descuentos\": 3000, \"gastosAdmin\": 15000, \"depreciacion\": 3000, \"devoluciones\": 2000, \"gastosVentas\": 10000, \"materiaPrima\": 40000, \"ventasBrutas\": 150000, \"cifProduccion\": 10000, \"manoObraDirecta\": 20000, \"gastosFinancieros\": 5000}','{\"colors\": {\"text\": \"#1f2937\", \"alert\": \"#ef4444\", \"accent\": \"#10b981\", \"primary\": \"#f39c12\", \"secondary\": \"#2c3e50\", \"background\": \"#ffffff\"}, \"logoUrl\": \"data:image/png;base64,\", \"socials\": {\"email\": \"\", \"phone\": \"\", \"tiktok\": \"\", \"website\": \"\", \"facebook\": \"\", \"location\": \"Hermosillo, Sonora, México\", \"whatsapp\": \"\", \"instagram\": \"\"}, \"brandName\": \"Cositas\", \"brandSlogan\": \"Inclusión Digital y Financiera\", \"fontPrimary\": \"\", \"businessType\": \"tecnologia\", \"brandDescription\": \"Ecosistema digital integral enfocado en el comercio hiper-local. Marketplace de MiPymes optimizado para dispositivos de gama baja.\"}','[{\"tipo\": \"Software\", \"monto\": 800000, \"fuente\": \"Programa\", \"cantidad\": 1, \"concepto\": \"Desarrollo App Nativa (Comprador)\"}, {\"tipo\": \"Software\", \"monto\": 500000, \"fuente\": \"Programa\", \"cantidad\": 1, \"concepto\": \"Desarrollo PWA (Vendedor)\"}, {\"tipo\": \"Software\", \"monto\": 600000, \"fuente\": \"Programa\", \"cantidad\": 1, \"concepto\": \"Asistente IA de Gestión\"}, {\"tipo\": \"Servicios\", \"monto\": 51000, \"fuente\": \"Programa\", \"cantidad\": 1, \"concepto\": \"Infraestructura Cloud (6 meses)\"}, {\"tipo\": \"Marketing\", \"monto\": 500000, \"fuente\": \"Programa\", \"cantidad\": 1, \"concepto\": \"Marketing Lanzamiento\"}, {\"tipo\": \"Capital\", \"monto\": 1200000, \"fuente\": \"Socios\", \"cantidad\": 1, \"concepto\": \"Cap